/*
 * High-performance portfolio calculations using C extension.
 * The list of lists passed in by the caller is copied in here row
 * at a time, which keeps the conversion out of the Python layer.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <math.h>
#include <stdlib.h>

static double *load_list_of_lists(PyObject *source, npy_intp *out_n) {
    npy_intp n = PyList_GET_SIZE(source);
    double *buf = (double *) malloc((size_t) n * (size_t) n * sizeof(double));
    if (buf == NULL) {
        PyErr_NoMemory();
        return NULL;
    }

    for (npy_intp i = 0; i < n; i++) {
        PyObject *row = PyList_GET_ITEM(source, i);
        if (PyList_GET_SIZE(row) != n) {
            free(buf);
            PyErr_Format(PyExc_ValueError,
                          "row %" NPY_INTP_FMT " has the wrong length", i);
            return NULL;
        }
        for (npy_intp j = 0; j < n; j++) {
            buf[i * n + j] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(row, j));
        }
    }
    *out_n = n;
    return buf;
}

static double *load_flat_list(PyObject *source, npy_intp *out_n) {
    npy_intp n = PyList_GET_SIZE(source);
    double *buf = (double *) malloc((size_t) n * sizeof(double));
    if (buf == NULL) {
        PyErr_NoMemory();
        return NULL;
    }
    for (npy_intp i = 0; i < n; i++) {
        buf[i] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(source, i));
    }
    *out_n = n;
    return buf;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    npy_intp nx, ns;
    double *x = load_flat_list(weights_obj, &nx);
    if (x == NULL) return NULL;
    double *s = load_list_of_lists(cov_obj, &ns);
    if (s == NULL) { free(x); return NULL; }

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < nx; i++) {
        double row_sum = 0.0;
        for (npy_intp j = 0; j < ns; j++) {
            row_sum += s[i * ns + j] * x[j];
        }
        risk_squared += x[i] * row_sum;
    }

    free(x);
    free(s);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    npy_intp nx, nr;
    double *x = load_flat_list(weights_obj, &nx);
    if (x == NULL) return NULL;
    double *r = load_flat_list(returns_obj, &nr);
    if (r == NULL) { free(x); return NULL; }

    double total_return = 0.0;
    for (npy_intp i = 0; i < nx; i++) {
        total_return += x[i] * r[i];
    }

    free(x);
    free(r);
    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    return PyModule_Create(&moduledef);
}
